// Initialize velocities from Maxwell-Boltzmann distribution
for (size_t i = 0; i < velocities.size(); ++i) {
    // Generate random velocity components from normal distribution
    // Standard normal distribution has mean 0 and variance 1
    // We need variance = kB * temperature / mass
    // So we scale by sqrt(kB * temperature / mass)
    double scale = sqrt_kT / std::sqrt(masses[i]);

    // Use rand() to generate uniform random numbers [0,1]
    // Convert to [-1,1] and then to normal distribution using Box-Muller transform
    // Since we need 3 components, we'll use a simple approach: generate uniform and transform
    double u1 = static_cast<double>(rand()) / RAND_MAX;
    double u2 = static_cast<double>(rand()) / RAND_MAX;

    // Box-Muller transform for two independent normal variables
    double z1 = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);
    double z2 = std::sqrt(-2.0 * std::log(u1)) * std::sin(2.0 * M_PI * u2);

    // Assign to x and y components
    velocities[i].x = z1 * scale;
    velocities[i].y = z2 * scale;

    // Generate third component
    u1 = static_cast<double>(rand()) / RAND_MAX;
    u2 = static_cast<double>(rand()) / RAND_MAX;
    z1 = std::sqrt(-2.0 * std::log(u1)) * std::cos(2.0 * M_PI * u2);
    velocities[i].z = z1 * scale;
}

